      's1.materials': { label: 'الأفلام أو المسلسلات أو الجمهور أو المواد', hint: 'ما الذي تحلله أو من تدرس.', ph: 'مثال: المسلسلات التركية المتاحة عبر منصات البث؛ نساء بين ١٨ و٣٠ عامًا' },
      's1.scope': { label: 'النطاق الجغرافي والثقافي', hint: 'الدول أو المجتمعات أو اللغات أو الحقب المشمولة.', ph: 'مثال: الرياض وجدة، المملكة العربية السعودية' },
      's1.venue': { label: 'نوع جهة النشر المستهدفة', hint: '' },
